/**
 * 孔径分布估算（基于 TPMS 场特征尺度）
 *
 * 物理约定（units.ts）：1 period = 1 mm，周期数 k 只改变总体尺寸，
 * 单胞尺寸恒为 1 mm —— 特征孔径只依赖单胞与孔隙率，与 k 无关：
 * d_pore ≈ 1mm × (porosity)^(1/3) × f(type)
 *
 * 其中 f(type) 为拓扑修正因子：
 * - Gyroid: 0.58
 * - Diamond: 0.52
 * - Schwarz P: 0.63
 * - I-WP: 0.55
 * - F-RD: 0.48
 * - Neovius: 0.60
 */

const PORE_FACTOR: Record<string, number> = {
  gyroid: 0.58,
  diamond: 0.52,
  'schwarz': 0.63,
  'i-wp': 0.55,
  'f-rd': 0.48,
  neovius: 0.60,
  lidinoid: 0.57,
  splitp: 0.54,
  // C2 扩展第一批：同量级估值（基准孔径系数，custom 回退口径一致）
  octo: 0.56,
  karcher: 0.58,
  fks: 0.55,
  fky: 0.57,
  gprime: 0.57,
  fcks: 0.55, // 谐波 3× 估值
  // C2 扩展第三批：同量级估值（custom 回退口径一致）
  dprime: 0.54,
  dp: 0.58,
  dd: 0.53,
  dg: 0.57,
  fcky: 0.57, // C2 扩展第四批：沿 fky 口径
  cdd: 0.54, // C2 扩展第五批：沿 diamond 族口径
  custom: 0.58,
};

export interface PoreStats {
  meanDiameter: number;       // 平均孔径 (mm)
  minDiameter: number;        // 最小孔径 (mm)
  maxDiameter: number;        // 最大孔径 (mm)
  stdDiameter: number;        // 标准差 (mm)
  surfaceToVolume: number;    // 比表面积 (mm²/mm³)
  tortuosity: number;         // 迂曲度
}

function mapType(type: string): string {
  if (type === 'iwp') return 'i-wp';
  if (type === 'frd') return 'f-rd';
  return type;
}

export function estimatePoreStats(
  porosity: number,
  type: string,
  svRatio: number
): PoreStats {
  const eps = porosity / 100;
  const factor = PORE_FACTOR[mapType(type)] ?? PORE_FACTOR['gyroid'];

  // 平均孔径：单胞恒 1mm（1 period=1mm），与周期数 cellSize 无关
  const meanDiameter = factor * Math.pow(eps, 1/3);

  // 孔径分布近似为正态，σ ≈ 0.15 × mean
  const stdDiameter = meanDiameter * 0.15;
  const minDiameter = Math.max(0.01, meanDiameter - 2 * stdDiameter);
  const maxDiameter = meanDiameter + 2 * stdDiameter;

  // 迂曲度估算：τ ≈ 1 + 0.5·(1-ε) (Mackie-Meares 近似)
  const tortuosity = 1 + 0.5 * (1 - eps);

  return {
    meanDiameter,
    minDiameter,
    maxDiameter,
    stdDiameter,
    surfaceToVolume: svRatio,
    tortuosity,
  };
}
