/**
 * URL 参数解析与序列化
 * 完全兼容原系统的 URL 参数恢复机制，确保旧版链接可正常解析加载。
 */

import type { AppState, TpmType, RenderModel, StructureMode, ContainerShape, MaterialPreset, GradientDirection, ColoringMode } from './types';
import { ENDPLATE_MAX_UI_MM, type BlendAxis } from './types';
// import { getDefaultWeights } from './core/tpms-functions'; // TODO: restore when used

const VALID = {
  type: ['gyroid','diamond','schwarz','neovius','iwp','frd','lidinoid','splitp','octo','karcher','fks','fky','gprime','fcks','dprime','dp','dd','dg','fcky','cdd','custom'] as TpmType[],
  model: ['surface','strut','solid'] as RenderModel[],
  structure: ['solid_network','shell','gradient_shell'] as StructureMode[],
  container: ['cube','cylinder'] as ContainerShape[],
  material: ['auto','tc4','polymer','thermal'] as MaterialPreset[],
  gradient: ['z','radial','spherical'] as GradientDirection[],
  coloring: ['none', 'field', 'elevation', 'mean_curvature', 'gauss_curvature', 'stress_vm'] as ColoringMode[],
};

function clamp(v: string | null, min: number, max: number, def: number): number {
  if (v == null || isNaN(+v)) return def;
  return Math.min(max, Math.max(min, +v));
}

/** 从 URL SearchParams 解析为状态 */
export function parseURLParams(search: string): Partial<AppState> {
  const q = new URLSearchParams(search);
  const state: Partial<AppState> = {};

  if (q.has('type') && VALID.type.includes(q.get('type') as TpmType)) {
    state.type = q.get('type') as TpmType;
  }
  if (q.has('model') && VALID.model.includes(q.get('model') as RenderModel)) {
    state.model = q.get('model') as RenderModel;
  }
  if (q.has('structure') && VALID.structure.includes(q.get('structure') as StructureMode)) {
    state.structureMode = q.get('structure') as StructureMode;
  }
  if (q.has('container') && VALID.container.includes(q.get('container') as ContainerShape)) {
    state.containerShape = q.get('container') as ContainerShape;
  }
  if (q.has('porosity')) {
    state.porosity = clamp(q.get('porosity'), 60, 90, 75);
  }
  if (q.has('cellSize')) {
    state.cellSize = clamp(q.get('cellSize'), 1, 5, 3);
  }
  if (q.has('thickness')) {
    state.thickness = clamp(q.get('thickness'), 0.5, 2.0, 1.0);
  }
  if (q.has('slice')) {
    state.slice = clamp(q.get('slice'), -100, 100, 100);
  }
  if (q.has('material') && VALID.material.includes(q.get('material') as MaterialPreset)) {
    state.material = q.get('material') as MaterialPreset;
  }

  // 顶点着色模式（白名单校验，未知值按默认单色处理）
  if (q.has('color') && VALID.coloring.includes(q.get('color') as ColoringMode)) {
    state.coloring = q.get('color') as ColoringMode;
  }

  // WebGPU 只是可选加速路径；缺省保持默认开启，显式 gpu=0 才关闭。
  if (q.has('gpu')) state.gpuAccelerate = q.get('gpu') !== '0';

  // 权重：仅 URL 显式携带 wa/wb/wc/wd 之一时覆盖。
  // 无条件覆盖会让 setState 的"类型变更重置为该类型默认权重"语义在 URL 路径永不生效
  //（当前各类型默认恰为全 1 故无害，未来默认非全 1 时会静默出错）
  if (q.has('wa') || q.has('wb') || q.has('wc') || q.has('wd')) {
    state.weights = [
      clamp(q.get('wa'), 0, 2, 1),
      clamp(q.get('wb'), 0, 2, 1),
      clamp(q.get('wc'), 0, 2, 1),
      clamp(q.get('wd'), 0, 2, 1),
    ];
  }

  // 自动旋转
  if (q.has('autoRotate')) {
    state.autoRotate = q.get('autoRotate') !== '0';
  }

  // 梯度方向（没有键时不写入 partial，交给当前默认状态）
  if (q.has('grad') && VALID.gradient.includes(q.get('grad') as GradientDirection)) {
    state.gradientDir = q.get('grad') as GradientDirection;
  }

  // 加载端板厚度（mm）；缺省时不覆盖当前状态
  if (q.has('ep')) state.endplateMm = clamp(q.get('ep'), 0, ENDPLATE_MAX_UI_MM, 0);
  // 【阶段 IV】空间映射恢复（白名单：kind 只允许已知映射族）
  if (q.has('mfd') && ['identity', 'cylinder', 'torus', 'hyperbolic', 'metric', 'poincare'].includes(q.get('mfd')!)) {
    state.manifold = {
      kind: q.get('mfd') as AppState['manifold']['kind'],
      radius: q.has('mfr') ? clamp(q.get('mfr'), 8, 30, 15) : 15,
      scale: clamp(q.get('mfs'), 0.25, 4, 1.4),
      axis: (q.get('mfa') === 'x' || q.get('mfa') === 'y' || q.get('mfa') === 'z')
        ? q.get('mfa') as AppState['manifold']['axis']
        : 'z',
    };
  }

  // 【v3.0 阶段 IV】应力场引导恢复（preset 白名单；数值 clamp）
  const sdRaw = q.get('sd');
  if (sdRaw && ['bending', 'cantilever', 'torsion'].includes(sdRaw)) {
    state.stress = {
      preset: sdRaw as AppState['stress']['preset'],
      strength: clamp(q.get('sds'), 0, 1, 0.5),
      anisotropy: clamp(q.get('sda'), 1, 2.5, 1.6),
    };
  }

  // 【v3.0 阶段 V】多级分形恢复（microType 白名单 = 已知 TPMS 族）
  const hdRaw = q.get('hd');
  if (hdRaw && ['gyroid', 'diamond', 'schwarz', 'neovius', 'iwp', 'frd', 'lidinoid', 'splitp', 'octo', 'karcher', 'fks', 'fky', 'gprime', 'fcks', 'dprime', 'dp', 'dd', 'dg', 'fcky', 'cdd'].includes(hdRaw)) {
    state.hierarchical = {
      enabled: true,
      microType: hdRaw as AppState['hierarchical']['microType'],
      frequency: Math.round(clamp(q.get('hn'), 3, 8, 4)),
      amplitude: clamp(q.get('hl'), 0.1, 0.5, 0.25),
    };
  }

  // 【v7.0 Stage I】隐式神经拓扑恢复（nz 打包 CSV：仅数字/逗号进入，逐值 clamp ±3）
  if (q.get('ne') === '1' && q.has('nz')) {
    const parts = (q.get('nz') ?? '').split(',');
    if (parts.length === 8 && parts.every((p) => /^-?\d+(\.\d+)?$/.test(p.trim()))) {
      state.neural = {
        enabled: true,
        z: parts.map((p) => Math.min(3, Math.max(-3, Number(p.trim())))),
      };
    }
  }

  // 剖切轴向 / 反向
  const sa = q.get('sa');
  if (sa === 'x' || sa === 'y' || sa === 'z') state.sliceAxis = sa;
  if (q.has('si')) state.sliceInvert = q.get('si') === '1';

  // 混合模式（hybridType/hybridBlend 必须过白名单：否则恶意 URL 可注入任意字符串，
  // 经导出脚本的单引号插值落地为可执行 Python/MATLAB 代码——任意代码执行）
  if (q.get('hybrid') === '1') {
    const rawTypeB = q.get('hybridType');
    const rawBlend = q.get('hybridBlend');
    state.hybrid = {
      enabled: true,
      // hybridType 剔除 custom：UI 无该按钮；curvature 路径 typeB=custom 会因空公式抛错（红队 D）
      typeB: rawTypeB && rawTypeB !== 'custom' && VALID.type.includes(rawTypeB as TpmType) ? (rawTypeB as TpmType) : 'diamond',
      blendFunction: rawBlend === 'linear' || rawBlend === 'sigmoid' ? rawBlend : 'sigmoid',
      // clamp 与 UI 滑块同域（红队 D：曾 [-2,2]/[0.1,5] 宽于 UI [-1,1]/[0.1,2]，分享链可产出面板不可回拨状态）
      blendCenter: clamp(q.get('hybridCenter'), -1, 1, 0),
      blendWidth: clamp(q.get('hybridWidth'), 0.1, 2.0, 1.0),
      axis: (['x','y','z','radial'].includes(q.get('hybridAxis') || '') ? q.get('hybridAxis') : 'x') as BlendAxis,
    };
  }

  // C1 渐变等值场（恶意 URL 数值全过 clamp 钳制；clamp 与 UI 滑块同域）
  if (q.get('ig') === '1') {
    state.isoGrad = {
      enabled: true,
      hard: clamp(q.get('igH'), -0.4, 0, -0.12),
      soft: clamp(q.get('igS'), 0, 0.4, 0.12),
      band: clamp(q.get('igB'), 0, 2, 0.4),
    };
  }

  // 自定义公式（URLSearchParams 已自动编解码，无需再包一层）
  if (q.has('formula')) {
    state.customFormula = q.get('formula') ?? '';
  }

  return state;
}

/** 在 init 之前解析 URL 参数到全局状态 */
export function initStateFromURL(): Partial<AppState> {
  if (!location.search || location.search.length <= 1) return {};
  return parseURLParams(location.search);
}
